total_num_cases = 63

for model in failed_case_names.keys():

    count_assumption_not_found = len(assumption_not_found_case_names[model])
    count_assumption_not_found_and_failure = len(assumption_not_found_case_names[model] & failed_case_names[model])
    count_assumption_not_found_no_failure = len(assumption_not_found_case_names[model] - failed_case_names[model])
    count_assumption_found_failure = len(failed_case_names[model] - assumption_not_found_case_names[model])
    count_assumption_found_no_failure = total_num_cases - len(assumption_not_found_case_names[model] | failed_case_names[model])

    print('\n\n## model:', model)
    print('assumption_not_found && failure:', count_assumption_not_found_and_failure, 'assumption_not_found && no_failure:',
          count_assumption_not_found_no_failure, 'assumptions_found && failure:', count_assumption_found_failure, 'assumptions_found && no_failure:', count_assumption_found_no_failure)

    contingency_table = np.array([
        [count_assumption_not_found_and_failure, count_assumption_not_found_no_failure],
        [count_assumption_found_failure, count_assumption_found_no_failure]
    ])

    #print("P(F|not A)", count_assumption_not_found_and_failure / (count_assumption_not_found_and_failure + count_assumption_not_found_no_failure))
    print("P(F|not A)", (count_assumption_not_found_and_failure + count_assumption_found_failure) / count_assumption_not_found_and_failure)
    #print("P(F|A)", count_assumption_found_failure / (count_assumption_found_failure + count_assumption_found_no_failure))

    from scipy.stats import chi2_contingency
    chi2, p, dof, expected = chi2_contingency(contingency_table)

    independent = p > 0.01
    print("Assumption not found and failure independent? ", independent)
    print("p-value from chi^2 test:", p)